import styled from "styled-components";

const TableContainer = styled.div`
  width: 100%;
  background: white;
  padding: 20px;
  border-radius: 8px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
  margin-top: 30px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
`;

const Title = styled.h3`
  font-size: 32px; /* Điều chỉnh cỡ chữ tại đây */
  font-weight: bold;
  margin-bottom: 30px;
  color: #333;
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
`;

const Th = styled.th`
  background: #d6d6d6;
  color: black;
  padding: 10px;
  text-align: left;
`;

const Td = styled.td`
  border: 1px solid #ddd;
  padding: 10px;
`;

const FastaTable = ({ sample }) => {
  return (
    <TableContainer>
      <Title>Fasta Sample Information</Title>
      <Table>
        <thead>
          <tr>
            <Th>Field</Th>
            <Th>Value</Th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <Td>Name</Td>
            <Td>{sample.name}</Td>
          </tr>
          <tr>
            <Td>Strain</Td>
            <Td>{sample.strain}</Td>
          </tr>
          <tr>
            <Td>Header</Td>
            <Td>{sample.header}</Td>
          </tr>
          <tr>
            <Td>Length</Td>
            <Td>{sample.length}</Td>
          </tr>
          <tr>
            <Td>Created Time</Td>
            <Td>{new Date(sample.createdAt).toLocaleString()}</Td>
          </tr>
        </tbody>
      </Table>
    </TableContainer>
  );
};

export default FastaTable;
